-- Migration 021: application-managed users, sessions, and OAuth transactions.
--
-- Neon PostgreSQL is the source of truth for application user records and for
-- BugWiser's own sessions. Nothing here depends on Supabase Auth: the `auth`
-- schema that previously issued user UUIDs is empty in Neon, so `public.users`
-- becomes the authoritative user table and new UUIDs are generated by the app.
--
-- Additive only:
--   * no existing row, column, index, or foreign key is dropped or rewritten,
--   * existing `users` rows keep their UUID, so every `analyses.user_id`,
--     `github_identities.user_id`, and `github_installation_users.user_id`
--     reference stays valid.
--
-- Rollback: supabase/rollback/021_neon_auth_sessions.sql

-- ── users: record how the row was provisioned ───────────────────────────────
-- Enum-free TEXT so a future provider (e.g. an enterprise IdP) needs no type
-- change. `github_app` covers both new sign-ins and rows migrated from the
-- former Supabase Auth user table.
ALTER TABLE users
  ADD COLUMN IF NOT EXISTS identity_source TEXT;

UPDATE users
   SET identity_source =
         CASE
           WHEN raw_user_meta_data->>'bugwiser_guest' = 'true' THEN 'guest'
           ELSE 'github_app'
         END
 WHERE identity_source IS NULL;

ALTER TABLE users
  DROP CONSTRAINT IF EXISTS users_identity_source_check;
ALTER TABLE users
  ADD CONSTRAINT users_identity_source_check
  CHECK (identity_source IS NULL OR identity_source IN ('github_app', 'guest'));

-- ── sessions: BugWiser's own server-side session records ────────────────────
-- The browser holds an opaque random id inside an HttpOnly signed cookie. Only
-- the SHA-256 of that id is stored, so a database read cannot be replayed as a
-- session. Expiry is enforced here and re-checked on every request.
CREATE TABLE IF NOT EXISTS sessions (
  token_hash   TEXT PRIMARY KEY,
  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at   TIMESTAMPTZ NOT NULL,
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at   TIMESTAMPTZ,
  CONSTRAINT sessions_expiry_after_creation CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);

-- ── oauth_transactions: one-time, browser-bound authorization attempts ──────
-- The PKCE verifier and return target live on the server, not in a cookie that
-- two tabs can overwrite. Consumption is a single conditional UPDATE, so a
-- state value can only be redeemed once even under concurrent callbacks.
CREATE TABLE IF NOT EXISTS oauth_transactions (
  state_hash    TEXT PRIMARY KEY,
  code_verifier TEXT NOT NULL,
  browser_hash  TEXT NOT NULL,
  return_to     TEXT NOT NULL DEFAULT '/dashboard',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at    TIMESTAMPTZ NOT NULL,
  consumed_at   TIMESTAMPTZ,
  CONSTRAINT oauth_transactions_expiry_after_creation CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS idx_oauth_transactions_expires_at
  ON oauth_transactions(expires_at);

-- Stale, unconsumed transactions are deleted by the start route before a new
-- one is created; no background job is required for correctness.
